import{t as e}from"./jsx-runtime-lw2jiZar.js";import{C as t,D as n,E as r,M as i,N as a,O as o,P as s,_ as c,b as l,k as u,l as d,n as f,o as p,s as m,t as h,u as g,w as _}from"./shared-DP9JVsk0.js";import{t as v}from"./copy-CHmcPNA5.js";import{t as y}from"./database-LLH4Psoh.js";import{t as b}from"./CodeEditor-BZlrvoTL.js";var x=e();function S({module:e}){return(0,x.jsxs)(a,{children:[(0,x.jsx)(i,{variant:`project`,chip:e??`Месяц 2 · Блок 8`,title:`37. MemoryStorage и один договор`,intro:`Добавим хранение в памяти к уже работающему файловому варианту. Сравним их через одинаковые действия и разберём, что именно копирует список.`,tags:[{icon:(0,x.jsx)(y,{size:14}),label:`два варианта хранения`},{icon:(0,x.jsx)(v,{size:14}),label:`контейнеры и ссылки`}]}),(0,x.jsxs)(s,{number:`00`,title:`Тот же сценарий, другое место хранения`,children:[(0,x.jsx)(o,{children:`После прошлого шага операции получают объект хранения, читают актуальный список и сохраняют изменения через load и save. Теперь проверим, какие обещания должны остаться прежними, если данные хранятся в памяти.`}),(0,x.jsx)(`p`,{children:`Временная память полезна для короткого запуска и проверки. Но нам важно не заменить один список другим случайно, а дать существующим операциям второй вариант с тем же договором. Поэтому начнём с результата прошлого шага, затем разберём владельцев списка и закончим сравнением двух storage.`}),(0,x.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`Операции уже получают JsonStorage и вызывают load/save.`},{title:`Новый вопрос`,description:`Какие результаты и эффекты должны совпадать у другого storage?`},{title:`Результат`,description:`Добавим MemoryStorage и проверим поведение операций на обоих вариантах.`}]}),(0,x.jsx)(`p`,{children:`Эти шаги соединены одним критерием: операция зависит от понятной роли хранения, а не от того, как устроен файл или внутренний список. При этом мы отдельно проследим, какие гарантии даёт копия контейнера и где ссылки на задачи остаются общими.`})]}),(0,x.jsxs)(s,{number:`01`,title:`Договор описывает поведение`,children:[(0,x.jsx)(o,{children:`Договор storage задаёт, что получает операция от load и какой результат передаёт в save. Этого достаточно, чтобы начать сравнение JsonStorage и MemoryStorage без базового класса.`}),(0,x.jsx)(`p`,{children:`У обеих реализаций совпадают имена методов, но одного совпадения синтаксиса мало. После load мы ожидаем список задач, с которым уже умеют работать операции. После save переданный список становится текущим сохранённым набором выбранного storage. Если один вариант вместо списка возвращает None или сохраняет не тот набор, одинаковая запись вызова не делает его совместимым.`}),(0,x.jsx)(`p`,{children:`Представим две кассы, которые принимают один и тот же номерной талон и выдают одинаковый чек. Нам не обязательно знать, кто построил кассу и из каких деталей она собрана. Для замены важно совпадение наблюдаемого поведения. Граница аналогии в том, что программа ещё проверяет типы данных, исключения и побочные эффекты; одного похожего чека недостаточно.`}),(0,x.jsx)(`p`,{children:`В нашем случае JsonStorage читает и записывает файл, а MemoryStorage будет держать набор в памяти процесса. Среда разная, но потребитель рассчитывает на один смысл load/save. Наследование не добавляет эту гарантию само: её задают договор и проверка реальных действий.`}),(0,x.jsx)(l,{question:`Что позволяет существующей операции использовать JsonStorage или MemoryStorage без переписывания?`,options:[`Одинаковое имя класса и общий базовый тип`,`Согласованные результаты load, смысл save и ожидаемые ошибки`,`Хранение данных в одном физическом файле`],correctIndex:1,explanation:`Операция зависит от результата и эффекта договора. Общий предок и одинаковые имена не заменяют совпадение поведения.`}),(0,x.jsx)(`p`,{children:`Мы не вводим отдельный интерфейс или новый сервис ради формальной архитектуры. Достаточно ограничить операцию известными вызовами storage и убедиться, что оба выбранных объекта отвечают на них одинаково по смыслу. Такое решение легче проверить, пока обе реализации доступны рядом.`})]}),(0,x.jsxs)(s,{number:`02`,title:`None и пустой список означают разное`,children:[(0,x.jsx)(o,{children:`MemoryStorage может получить начальные задачи, а может начаться пустым. Для конструктора важно отличить отсутствие аргумента от списка, который передан намеренно.`}),(0,x.jsx)(`p`,{children:`None служит здесь признаком «начальные данные не заданы». Тогда создаётся новый пустой контейнер. Переданный список задаёт стартовое содержимое, даже если в нём пока нет элементов. В обоих случаях число задач сначала может быть нулевым, но причина этого результата разная: в первом случае данных не передали, во втором явно передали пустой набор.`}),(0,x.jsx)(`p`,{children:`Сравним это с пустой коробкой и отсутствием заказа на коробку. Снаружи обе ситуации выглядят пустыми, но решение о создании и владении контейнером принимается по разному сигналу. В Python проверка tasks or [] стирает это различие, потому что пустой список считается ложным. Проверка is None выражает намерение прямо.`}),(0,x.jsx)(b,{caption:`начальное состояние MemoryStorage`,code:`class MemoryStorage:
    def __init__(self, tasks=None):
        self._tasks = list(tasks) if tasks is not None else []`}),(0,x.jsx)(`p`,{children:`Конструктор создаёт собственный список. Если список передан, list(tasks) копирует его элементы в новый контейнер. Если передан None, выражение после else создаёт пустой контейнер именно для этого экземпляра. Поэтому два хранилища по умолчанию не начинают делить одну изменяемую переменную.`}),(0,x.jsx)(r,{tone:`info`,children:`Проверяем None явно. Изменяемый список не ставим значением по умолчанию в параметре: он мог бы пережить вызов конструктора и стать общим для нескольких объектов.`})]}),(0,x.jsxs)(s,{number:`03`,title:`Копия списка не копирует его элементы`,children:[(0,x.jsx)(o,{children:`При load и save нам нужна отдельная структура списка, чтобы внешнее добавление или удаление элемента не меняло внутренний набор молча. Но задачи внутри остаются теми же объектами.`}),(0,x.jsx)(`p`,{children:`Вспомним знакомую поверхностную копию контейнера: list(tasks) создаёт другой список, но не вызывает конструктор заново для каждой задачи. Полезна аналогия с двумя папками-описями, в которых записаны ссылки на одни и те же дела. Можно вычеркнуть строку из одной описи, не меняя другую; если же открыть дело по ссылке и исправить сам документ, изменение видно через обе описи. В Python роль описи играет контейнер, а задачу представляет объект Task. Аналогия заканчивается здесь: переменная хранит ссылку на объект, а не путь к отдельному бумажному листу.`}),(0,x.jsxs)(h,{caption:`Два списка содержат ссылки на одну Task`,orientation:`vertical`,children:[(0,x.jsxs)(m,{title:`Контейнеры разделены, объект задачи общий`,children:[(0,x.jsxs)(p,{label:`Внутренний список MemoryStorage`,children:[(0,x.jsx)(d,{title:`MemoryStorage._tasks`,shape:`database`,children:(0,x.jsx)(`p`,{children:`Внутренний контейнер`})}),(0,x.jsx)(f,{label:`содержит ссылку`}),(0,x.jsx)(d,{title:`Task с id 7`,children:(0,x.jsx)(`p`,{children:`Один объект задачи`})})]}),(0,x.jsxs)(p,{label:`Список, который вернул load`,children:[(0,x.jsx)(d,{title:`tasks в операции`,shape:`database`,children:(0,x.jsx)(`p`,{children:`Новый контейнер списка`})}),(0,x.jsx)(f,{label:`содержит ссылку на ту же Task`}),(0,x.jsx)(d,{title:`Task с id 7`,children:(0,x.jsx)(`p`,{children:`Тот же объект, не его копия`})})]})]}),(0,x.jsx)(g,{title:`Что отсюда следует`,children:(0,x.jsx)(`p`,{children:`Изменение состава одного списка не меняет другой. Изменение поля общей Task видно через обе ссылки.`})})]}),(0,x.jsx)(`p`,{children:`Сначала читаем схему по двум строкам. Верхняя показывает контейнер, которым владеет MemoryStorage. Нижняя показывает отдельный список, полученный операцией при load. Стрелки от обоих контейнеров приходят к Task с id 7: копировались списки, но не сама задача. Это предел гарантии, который нельзя описывать как полную изоляцию.`}),(0,x.jsx)(c,{code:`class Note:
    def __init__(self, title):
        self.title = title

original = [Note('черновик')]
returned = list(original)
returned.append(Note('новая заметка'))
returned[0].title = 'исправлено'
print(len(original))
print(original[0].title)`,output:`1
исправлено`,hint:`Сначала отдельно проследим два контейнера, затем проверим, указывают ли первые элементы на один объект.`}),(0,x.jsx)(`p`,{children:`В выводе исходный список по-прежнему содержит один элемент: добавление произошло в returned. Но заголовок первого объекта изменился и в original, потому что оба списка содержат ссылку на ту же Note. Точно так же список-копия с Task защищает структуру набора от append/remove снаружи, но не отменяет мутацию самой задачи.`})]}),(0,x.jsxs)(s,{number:`04`,title:`MemoryStorage реализует знакомые операции`,children:[(0,x.jsx)(o,{children:`Теперь мы можем записать память через тот же небольшой набор методов. Класс отвечает за контейнер списка; операции Planner по-прежнему решают, какую задачу добавить, найти или завершить.`}),(0,x.jsx)(`p`,{children:`Конструктор хранит начальный контейнер отдельно. Метод load возвращает новую копию списка, а save принимает текущий результат операции и сохраняет его копию. Важно, что save не добавляет отдельный элемент и не выполняет прикладное действие. Он заменяет сохранённый набор переданным снимком, как это ожидает уже знакомая операция.`}),(0,x.jsx)(`p`,{children:`Мы можем думать о MemoryStorage как о выдвижном ящике с описью. Операция получает свою копию описи, меняет её и возвращает новую версию через save. Она не должна заглядывать во внутренний ящик и править поле _tasks напрямую. Предел этой аналогии такой же: карточки в двух описях могут указывать на один объект Task, поэтому изменение поля объекта заметно сразу.`}),(0,x.jsx)(b,{caption:`полная реализация MemoryStorage`,code:`class MemoryStorage:
    def __init__(self, tasks=None):
        self._tasks = list(tasks) if tasks is not None else []

    def load(self):
        return list(self._tasks)

    def save(self, tasks):
        self._tasks = list(tasks)`}),(0,x.jsxs)(`ul`,{children:[(0,x.jsx)(`li`,{children:`__init__ отделяет внутренний список от переданного контейнера и не хранит общий изменяемый default.`}),(0,x.jsx)(`li`,{children:`load возвращает новый контейнер, поэтому append или remove на результате не меняют состав _tasks до save.`}),(0,x.jsx)(`li`,{children:`save отделяет новый внутренний контейнер от переданного списка, но сохраняет ссылки на те же объекты Task.`})]}),(0,x.jsx)(`p`,{children:`В этом классе нет add_task, поиска или статистики. Такие действия принадлежат уже существующим операциям. Их порядок остаётся знакомым: получить список через load, выполнить предметное изменение и вызвать save, когда договор операции подтверждает изменение. Читающие действия не должны записывать снимок без причины.`}),(0,x.jsx)(_,{title:`Собираем один путь изменения`,label:`ПОРЯДОК РАБОТЫ`,prompt:`Мы получили отдельный список через load и хотим добавить в него задачу. Соберите передачу нового набора storage.`,pieces:[{id:`load`,code:`tasks = storage.load()`,note:`получаем список для операции`},{id:`append`,code:`tasks.append(task)`,note:`меняем локальный контейнер`},{id:`save`,code:`storage.save(tasks)`,note:`передаём новый снимок`},{id:`private`,code:`storage._tasks.append(task)`,note:`обход публичного договора`}],correctOrder:[`load`,`append`,`save`],explanation:`Мы меняем результат load, а затем явно передаём его через save. Так обе реализации storage получают изменение по одному договору.`,incorrectExplanation:`Сверим границу: операция получает список через load, меняет свой контейнер и передаёт его через save. К _tasks она не обращается.`})]}),(0,x.jsxs)(s,{number:`05`,title:`Один набор операций, два storage`,children:[(0,x.jsx)(o,{children:`Заменяемость проверяется на уже существующем сценарии. Мы выбираем один storage, передаём его операции и сравниваем предметный результат с запуском того же сценария через другой вариант.`}),(0,x.jsx)(`p`,{children:`Для честного сравнения начнём с одинакового содержимого и одинаковых команд. Через JsonStorage проверим чтение и запись на отдельном учебном пути. Через MemoryStorage выполним те же действия на копии исходного набора. Рабочий data/tasks.json останется обычной опорой приложения и не станет экспериментальным файлом.`}),(0,x.jsx)(`p`,{children:`После добавления обе версии должны сообщить о новой задаче с тем же назначенным по действующему правилу id. Поиск по id находит её, поиск по названию возвращает те же совпадения, завершение меняет is_done, а статистика считает одинаковые данные. Мы сравниваем наблюдаемое поведение операций, не внутреннее устройство файла и списка.`}),(0,x.jsx)(`p`,{children:`Чтение и поиск не меняют набор, поэтому им не нужен save. Ошибка ввода, неизвестный id и повторное завершение сохраняют прежний смысл; MemoryStorage не должен превращать отказ в успешное изменение. Если существующая операция вызывает save только после реального перехода, эта граница остаётся такой же и для памяти.`}),(0,x.jsx)(`p`,{children:`Важно запускать по очереди один вариант хранения. Если одновременно направить одни и те же действия в память и файл, получится уже другой сценарий с двумя состояниями. Если передать одной и той же Task в две начальные коллекции, появится общая ссылка между проверками и результат станет труднее объяснить. Для сравнения готовим независимые объекты с одинаковыми значениями.`}),(0,x.jsx)(t,{code:`class MemoryStorage:
    def load(self):
        return self._tasks`,question:`Какой договор нарушен, если внешний код вызвал tasks = storage.load(); tasks.clear()?`,options:[`Внутренний контейнер изменился без save, потому что load вернул его напрямую`,`Копирование списка не создало новые объекты Task`,`JsonStorage не смог открыть файл`],correctIndex:0,explanation:`Метод отдаёт сам внутренний контейнер. Публичный load должен вернуть list(self._tasks). Это создаст копию списка, но не Task внутри него.`,fix:`class MemoryStorage:
    def load(self):
        return list(self._tasks)`}),(0,x.jsx)(`p`,{children:`Если load возвращает внутренний список, вызывающий код может очистить его или изменить состав без вызова save. Исправление касается контейнера. Оно намеренно не копирует каждую Task, потому что глубокое копирование не входит в договор этой модели и поменяло бы уже обсуждённые ссылки.`}),(0,x.jsx)(`p`,{children:`Наконец, проверим место выбора. В рамках этого занятия конкретный сценарий получает либо JsonStorage, либо MemoryStorage. Обычный запуск приложения по-прежнему создаёт JsonStorage с рабочим путём. Здесь ещё не появляется build_service, не меняется точка сборки и не создаётся PlannerService: следующий шаг перенесёт туда читающие операции.`}),(0,x.jsx)(r,{tone:`warn`,children:`MemoryStorage помогает выполнить сценарий в текущем процессе, но новый экземпляр не восстанавливает прошлую сессию. Для обычного запуска и перезапуска остаётся JsonStorage.`})]}),(0,x.jsxs)(s,{number:`06`,title:`Проверяем результат и границы`,children:[(0,x.jsx)(o,{children:`Когда оба storage проходят одинаковые сценарии, мы можем считать их заменяемыми для этих операций. Теперь зафиксируем, что именно подтверждает такая проверка и чего она не обещает.`}),(0,x.jsx)(`p`,{children:`Сначала сравним предметные результаты: значения задач и статистику после одинаковой последовательности действий. Затем отдельно проверим владение контейнерами: изменение списка, который вернул load, не меняет внутренний состав без save; список, переданный в save, после вызова можно менять отдельно. Наконец, проверим общий объект Task: изменение его поля через одну ссылку видно при следующем чтении памяти.`}),(0,x.jsx)(`p`,{children:`Эти проверки не доказывают изоляцию всего состояния и не обещают откат. Если операция меняет Task напрямую и затем завершается до save, ссылка в MemoryStorage уже может показать это изменение. JsonStorage возвращает новые Task из файла, поэтому поведение при таком отказе может отличаться. В принятом последовательном сценарии успешные операции сохраняют результат как обычно; транзакции и параллельная запись здесь не вводятся.`}),(0,x.jsx)(`p`,{children:`Вторая граница касается ошибок. JsonStorage способен сообщить о проблеме файла, а MemoryStorage не открывает файл и не создаёт такой отказ. Совместимый договор не означает одинаковую причину всех возможных ошибок. Мы сохраняем публичный смысл операции и не маскируем StorageError, если выбранный вариант не смог завершить сохранение.`}),(0,x.jsx)(`p`,{children:`После этих сравнений прежний путь должен оставаться рабочим: штатный запуск читает и сохраняет JSON, а list/find/search/done/stats дают тот же результат, что до добавления памяти. Мы не заменяем storage по умолчанию на MemoryStorage и не переносим выбор зависимости в него. Так новое средство проверки дополняет приложение, не вытесняя постоянное хранение.`}),(0,x.jsx)(l,{question:`Что гарантирует shallow copy списка задач?`,options:[`Новый список и независимые копии всех Task`,`Новый контейнер списка, но те же ссылки на Task`,`Откат любой мутации, если save не вызван`],correctIndex:1,explanation:`Копируется контейнер верхнего уровня. Элементы остаются теми же объектами, поэтому мутация Task видна через обе ссылки.`})]}),(0,x.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(o,{children:`В практике мы добавим второй вариант storage рядом с файловым и пропустим через него знакомые операции. Результат должен объяснять как заменяемость, так и границу копирования.`}),(0,x.jsx)(u,{variant:`connected`,items:[{title:`Добавим MemoryStorage`,description:`Получим тот же договор load/save и отдельные контейнеры.`},{title:`Проследим ссылки`,description:`Увидим разницу между изменением списка и изменением Task.`},{title:`Сравним операции`,description:`Получим те же результаты на памяти и изолированном JSON-пути.`},{title:`Повторим обычный запуск`,description:`Убедимся, что приложение всё ещё использует JsonStorage.`}]}),(0,x.jsx)(`p`,{children:`Начнём с реального storage и уже существующих переходных операций. Для файловой проверки используем отдельный путь и одинаковые исходные значения; для сравнения создадим независимые Task. В конце проверим прежние действия и перезапуск через обычное приложение.`}),(0,x.jsx)(`p`,{children:`Так мы подтвердим общий договор на выбранном storage и сохраним JSON как обычный запуск. Результат станет опорой следующего занятия: PlannerService перенесёт читающие сценарии на тот же storage, а add и done пока останутся в переходных операциях.`})]}),(0,x.jsx)(n,{points:[`MemoryStorage реализует тот же load/save, что и JsonStorage.`,`Пустой список и None различаются при выборе начального состояния.`,`Копия контейнера не копирует сами Task.`,`Обычный запуск и перезапуск продолжают использовать JSON.`]})]})}export{S as Lesson37};